#include <cmath>

class Solution {
public:
    int minPrimes(int target) {
        auto is_prime = [](int n) {
            if (n < 2) return false;
            for (int d = 2; d * d <= n; ++d) {
                if (n % d == 0) return false;
            }
            return true;
        };

        if (is_prime(target)) return 1;
        if (target % 2 == 0) return 2;
        if (is_prime(target - 2)) return 2;
        return 3;
    }
};

class Solution {
    public int minPrimes(int target) {
        if (isPrime(target)) return 1;
        if (target % 2 == 0) return 2;
        if (isPrime(target - 2)) return 2;
        return 3;
    }

    private boolean isPrime(int n) {
        if (n < 2) return false;
        for (int d = 2; d * d <= n; d++) {
            if (n % d == 0) return false;
        }
        return true;
    }
}

