var minPrimes = function(target) {
    const isPrime = (n) => {
        if (n < 2) return false;
        for (let d = 2; d * d <= n; d++) {
            if (n % d === 0) return false;
        }
        return true;
    };

    if (isPrime(target)) return 1;
    if (target % 2 === 0) return 2;
    if (isPrime(target - 2)) return 2;
    return 3;
};
